/*
 * A287304  Primes that can be generated by the concatenation in base 5, in
 *          ascending order, of two consecutive integers read in base 10.
 * https://oeis.org/A287304
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) = the n-th prime that can be obtained by concatenating *
 *            the base‑5 representations of two consecutive integers k and
 *            k+1, * then interpreting the concatenation as a base‑5 number
 * Range:     u8 n <= 5, u16 n <= 44, u32 n <= 44, u64 n <= 44, u128 n <= 44,
 *            big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdbool.h>
#include "../utils/is_prime_big.h"

seq_t a(idx_t n) {
    idx_t count = 0;
    idx_t k = 1;
    while (true) {
        /* number of digits of k in base 5 */
        int len_k = 0;
        idx_t tmp = k;
        while (tmp) { len_k++; tmp /= 5; }
        /* number of digits of k+1 in base 5 */
        int len_k1 = 0;
        tmp = k + 1;
        while (tmp) { len_k1++; tmp /= 5; }

        /* compute 5^len_k1 */
        seq_t pow5 = 1;
        for (int i = 0; i < len_k1; ++i) pow5 *= 5;

        /* value obtained by concatenation: k*5^len(k+1) + (k+1) */
        seq_t val = (seq_t)k * pow5 + (seq_t)(k + 1);

        if (is_prime_big(val)) {
            ++count;
            if (count == n) return val;
        }
        ++k;
    }
}
